window.__PACK__=window.__PACK__||{};window.__PACK__["b7a"]={"rev":"y5o42y","lessons":[{"id":"l1","title":"درس اول: الحروف العربیة","fullHtml":"<!-- TAB: محتوا -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🔤 الدرس الأول: الحروف العربیة</h2>\n<p style=\"color:#cbd5e1; line-height:1.9;\">در این درس با حروف الفبای عربی و تلفظ درست آنها، همچنین با برخی کلمات پرکاربرد آشنا می‌شویم.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">المعجم (واژه‌نامه)</h3>\n<table style=\"width:100%; border-collapse:collapse; margin:15px 0; background:rgba(255,255,255,0.05); border-radius:10px; overflow:hidden; text-align:center;\">\n    <tr style=\"background:rgba(5,150,105,0.3); color:#fff;\">\n        <th style=\"padding:10px; border-bottom:1px solid rgba(255,255,255,0.1);\">عربی</th>\n        <th style=\"padding:10px; border-bottom:1px solid rgba(255,255,255,0.1);\">فارسی</th>\n        <th style=\"padding:10px; border-bottom:1px solid rgba(255,255,255,0.1);\">عربی</th>\n        <th style=\"padding:10px; border-bottom:1px solid rgba(255,255,255,0.1);\">فارسی</th>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">أَطْفال</td><td style=\"padding:10px; color:#cbd5e1;\">کودکان</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">بُلْبُل</td><td style=\"padding:10px; color:#cbd5e1;\">بلبل</td>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">تُوت</td><td style=\"padding:10px; color:#cbd5e1;\">توت</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">ثُرَیّا</td><td style=\"padding:10px; color:#cbd5e1;\">ثریا (نام دختر)</td>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">جَزیرَة</td><td style=\"padding:10px; color:#cbd5e1;\">جزیره</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">حُروف</td><td style=\"padding:10px; color:#cbd5e1;\">حروف</td>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">خَیّاط</td><td style=\"padding:10px; color:#cbd5e1;\">خیاط</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">دُعاء</td><td style=\"padding:10px; color:#cbd5e1;\">دعا</td>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">ذِهْن</td><td style=\"padding:10px; color:#cbd5e1;\">ذهن</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">رُکوع</td><td style=\"padding:10px; color:#cbd5e1;\">رکوع</td>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">سُجود</td><td style=\"padding:10px; color:#cbd5e1;\">سجده</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">شَهید</td><td style=\"padding:10px; color:#cbd5e1;\">شهید</td>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">صُندوق</td><td style=\"padding:10px; color:#cbd5e1;\">صندوق</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">ضَعْف</td><td style=\"padding:10px; color:#cbd5e1;\">ضعف</td>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">طَبَق</td><td style=\"padding:10px; color:#cbd5e1;\">ظرف، بشقاب</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">ظَرْف</td><td style=\"padding:10px; color:#cbd5e1;\">ظرف</td>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">عَسَل</td><td style=\"padding:10px; color:#cbd5e1;\">عسل</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">غَزال</td><td style=\"padding:10px; color:#cbd5e1;\">آهو</td>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">فیل</td><td style=\"padding:10px; color:#cbd5e1;\">فیل</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">قَلَم</td><td style=\"padding:10px; color:#cbd5e1;\">قلم</td>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">کِتاب</td><td style=\"padding:10px; color:#cbd5e1;\">کتاب</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">لَیْل</td><td style=\"padding:10px; color:#cbd5e1;\">شب</td>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">مُعَلِّم</td><td style=\"padding:10px; color:#cbd5e1;\">معلم</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">نَهْر</td><td style=\"padding:10px; color:#cbd5e1;\">رود</td>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">وَرْدَة</td><td style=\"padding:10px; color:#cbd5e1;\">گل</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">هُدْهُد</td><td style=\"padding:10px; color:#cbd5e1;\">هدهد</td>\n    </tr>\n    <tr>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">یَد</td><td style=\"padding:10px; color:#cbd5e1;\">دست</td>\n        <td style=\"padding:10px;\"></td><td style=\"padding:10px;\"></td>\n    </tr>\n</table>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">مذکر و مؤنث</h3>\n<p style=\"color:#cbd5e1; line-height:1.9;\">در زبان عربی هر اسمی یا مذکر است یا مؤنث. نشانه اصلی اسم مؤنث «ة» (تاء مربوطة) است.</p>\n<div style=\"background:rgba(16,185,129,0.1); border-right:4px solid #10b981; padding:15px; border-radius:10px; margin:15px 0; text-align:center; direction:rtl;\">\n    <span style=\"font-size:1.4rem; color:#fde68a; font-family:'Traditional Arabic', serif;\">هذا طالِبٌ. (این دانش‌آموز پسر است)</span><br>\n    <span style=\"font-size:1.4rem; color:#fde68a; font-family:'Traditional Arabic', serif; margin-top:10px; display:block;\">هذِهِ طالِبَةٌ. (این دانش‌آموز دختر است)</span>\n</div>\n\n<div style=\"background:rgba(251,191,36,0.15); border-right:4px solid #fbbf24; padding:15px; border-radius:10px; margin:15px 0; color:#fde68a; line-height:1.8;\">\n    💡 <strong>نکته:</strong> اسم‌های مذکر نشانه خاصی ندارند و باید با توجه به معنا و شناخت کلمه تشخیص داده شوند.\n</div>\n\n\n<!-- TAB: نمودار درختی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🌳 نمودار درختی الحروف العربیة</h2>\n<div class=\"xmind-container\">\n    <div class=\"xmind-root\">الحروف العربیة</div>\n    <div class=\"xmind-branches\">\n        <div class=\"xmind-branch\">\n            <div class=\"xmind-node\"><strong>الفبای عربی</strong>۲۸ حرف</div>\n        </div>\n        <div class=\"xmind-branch\">\n            <div class=\"xmind-node\"><strong>واژگان پایه</strong>أطفال، بلبل...</div>\n        </div>\n        <div class=\"xmind-branch\">\n            <div class=\"xmind-node\"><strong>مذکر و مؤنث</strong>نشانه مؤنث: ة</div>\n        </div>\n        <div class=\"xmind-branch\">\n            <div class=\"xmind-node\"><strong>اسم اشاره</strong>هذا، هذه</div>\n        </div>\n        <div class=\"xmind-branch\">\n            <div class=\"xmind-node\"><strong>جمله اسمیه</strong>هذا طالبٌ</div>\n        </div>\n    </div>\n</div>\n\n\n<!-- TAB: نکات امتحانی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">📝 نکات امتحانی درس اول</h2>\n<p style=\"color:#cbd5e1; margin-bottom:15px;\">مهم‌ترین نکاتی که برای موفقیت در امتحان این درس باید به آن‌ها توجه کنید:</p>\n\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۱: نشانه مؤنث</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">بیشتر اسم‌های مؤنث به «ة» ختم می‌شوند: طالبة، معلمة، شجرة.</p>\n</div>\n\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۲: هذا و هذه</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">«هذا» برای اشاره به اسم مذکر و «هذه» برای اشاره به اسم مؤنث استفاده می‌شود.</p>\n</div>\n\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۳: حروف شمسی و قمری</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">حروف شمسی (ت، ث، د، ذ، ر، ز، س، ش، ص، ض، ط، ظ، ل، ن) و حروف قمری بقیه حروف هستند.</p>\n</div>\n\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۴: تلفظ حروف</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">به تلفظ صحیح حروفی مانند (ح، ع، غ، ض، ط، ظ) دقت کنید.</p>\n</div>\n\n\n<!-- TAB: آزمون -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🧪 آزمون درس اول</h2>\n<p style=\"color:#cbd5e1; margin-bottom:20px;\">به سوالات زیر پاسخ دهید:</p>\n\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۱. کدام کلمه مؤنث است؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">\n        الف) طالِب &nbsp;&nbsp;&nbsp; ب) مُعَلِّم &nbsp;&nbsp;&nbsp; <strong>ج) طالِبَة</strong> &nbsp;&nbsp;&nbsp; د) کِتاب\n    </div>\n</div>\n\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۲. برای اشاره به «این (مذکر)» از کدام کلمه استفاده می‌شود؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">\n        الف) هذه &nbsp;&nbsp;&nbsp; <strong>ب) هذا</strong> &nbsp;&nbsp;&nbsp; ج) ذلک &nbsp;&nbsp;&nbsp; د) تلک\n    </div>\n</div>\n\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۳. نشانه اصلی اسم مؤنث چیست؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">\n        الف) ـه &nbsp;&nbsp;&nbsp; <strong>ب) ـة</strong> &nbsp;&nbsp;&nbsp; ج) ـون &nbsp;&nbsp;&nbsp; د) ـین\n    </div>\n</div>\n\n<div style=\"background:rgba(251,191,36,0.15); border-right:4px solid #fbbf24; padding:15px; border-radius:10px; color:#fde68a;\">\n    💡 <strong>پاسخ‌نامه:</strong> ۱ (ج)، ۲ (ب)، ۳ (ب)\n</div>\n\n\n<!-- TAB: گام به گام -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">✍️ گام به گام درس اول (صفحات ۱۰ تا ۱۴)</h2>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">۱. معنی کلمات صفحه ۱۰</h3>\n<table style=\"width:100%; border-collapse:collapse; margin:15px 0; background:rgba(255,255,255,0.05); border-radius:10px; overflow:hidden; text-align:center;\">\n    <tr style=\"background:rgba(5,150,105,0.3); color:#fff;\">\n        <th style=\"padding:10px; border-bottom:1px solid rgba(255,255,255,0.1);\">عربی</th>\n        <th style=\"padding:10px; border-bottom:1px solid rgba(255,255,255,0.1);\">فارسی</th>\n        <th style=\"padding:10px; border-bottom:1px solid rgba(255,255,255,0.1);\">عربی</th>\n        <th style=\"padding:10px; border-bottom:1px solid rgba(255,255,255,0.1);\">فارسی</th>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">أَب</td><td style=\"padding:10px; color:#cbd5e1;\">پدر</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">أَبی</td><td style=\"padding:10px; color:#cbd5e1;\">پدرم</td>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">أُحِبُّ</td><td style=\"padding:10px; color:#cbd5e1;\">دوست دارم</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">أُمّ</td><td style=\"padding:10px; color:#cbd5e1;\">مادر</td>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">أُمّی</td><td style=\"padding:10px; color:#cbd5e1;\">مادرم</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">أَنا</td><td style=\"padding:10px; color:#cbd5e1;\">من</td>\n    </tr>\n    <tr>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">هذا</td><td style=\"padding:10px; color:#cbd5e1;\">این (آقا)</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">هذه</td><td style=\"padding:10px; color:#cbd5e1;\">این (خانم)</td>\n    </tr>\n</table>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">۲. ترجمه الحوار (گفت‌وگو) صفحه ۱۴</h3>\n<div style=\"direction:rtl; font-family:'Traditional Arabic', serif; font-size:1.2rem; color:#fde68a; line-height:2.2; text-align:right; padding:15px; background:rgba(0,0,0,0.2); border-radius:10px;\">\n    أَنَا أَحمَد. (من احمد هستم)<br>\n    هُذا أَبی. (این پدرم است)<br>\n    أَنَا أُحِبُّ أَبی. (من پدرم را دوست دارم)<br>\n    أَنَا زَهراء. (من زهرا هستم)<br>\n    هذِهِ أُمّی. (این مادرم است)<br>\n    أَنَا أُحِبُّ أُمّی. (من مادرم را دوست دارم)\n</div>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">۳. پاسخ تمرین اول صفحه ۱۴ (أکمل الفراغ)</h3>\n<ul style=\"color:#cbd5e1; line-height:2; padding-right:20px;\">\n    <li><span style=\"color:#fde68a; font-family:'Traditional Arabic', serif; font-size:1.2rem;\">أَنا <strong>أَحمَد</strong>.</span> (من احمد هستم)</li>\n    <li><span style=\"color:#fde68a; font-family:'Traditional Arabic', serif; font-size:1.2rem;\">هذا <strong>أَبی</strong>.</span> (این پدرم است)</li>\n    <li><span style=\"color:#fde68a; font-family:'Traditional Arabic', serif; font-size:1.2rem;\">أَنا <strong>أُحِبُّ</strong> أَبی.</span> (من پدرم را دوست دارم)</li>\n    <li><span style=\"color:#fde68a; font-family:'Traditional Arabic', serif; font-size:1.2rem;\">مَن <strong>هذا</strong>؟</span> (این کیست؟)</li>\n    <li><span style=\"color:#fde68a; font-family:'Traditional Arabic', serif; font-size:1.2rem;\">مَن <strong>هذه</strong>؟</span> (این کیست؟ - مؤنث)</li>\n</ul>","r":"1g0xljy"},{"id":"l_1792499305336","title":"درس دوم","fullHtml":"<!-- TAB: محتوا -->\n<p style=\" margin-bottom:15px;\">🏫 الدرس الثاني: فی الصف</p>\n<p style=\" line-height:1.9;\">در این درس با کلمات مربوط به کلاس درس و گفت‌وگوی ساده آشنا می‌شویم.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">المعجم (واژه‌نامه)</h3>\n<table style=\"width:100%; border-collapse:collapse; margin:15px 0; background:rgba(255,255,255,0.05); border-radius:10px; overflow:hidden; text-align:center;\">\n    <tbody><tr style=\"background:rgba(5,150,105,0.3); color:#fff;\">\n        <th style=\"padding:10px; border-bottom:1px solid rgba(255,255,255,0.1);\">عربی</th>\n        <th style=\"padding:10px; border-bottom:1px solid rgba(255,255,255,0.1);\">فارسی</th>\n        <th style=\"padding:10px; border-bottom:1px solid rgba(255,255,255,0.1);\">عربی</th>\n        <th style=\"padding:10px; border-bottom:1px solid rgba(255,255,255,0.1);\">فارسی</th>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">شَجَرَة</td><td style=\"padding:10px; \">درخت</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">صَفّ</td><td style=\"padding:10px; \">کلاس</td>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">طالِب</td><td style=\"padding:10px; \">دانش‌آموز پسر</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">طالِبَة</td><td style=\"padding:10px; \">دانش‌آموز دختر</td>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">أُستاذ</td><td style=\"padding:10px; \">استاد</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">إِسْمُکَ</td><td style=\"padding:10px; \">نام تو</td>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">إِسْمي</td><td style=\"padding:10px; \">نام من</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">طَبیب</td><td style=\"padding:10px; \">پزشک</td>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">أَهْلاً بِکُمْ</td><td style=\"padding:10px; \">خوش آمدید</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">غُرْفَة</td><td style=\"padding:10px; \">اتاق</td>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">بِنْت</td><td style=\"padding:10px; \">دختر</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">کَیْفَ؟</td><td style=\"padding:10px; \">چطور؟</td>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">لُغَة</td><td style=\"padding:10px; \">زبان</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">مُبْتَسِماً</td><td style=\"padding:10px; \">خندان</td>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">تَلامیذ</td><td style=\"padding:10px; \">دانش‌آموزان</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">حَقیبَة</td><td style=\"padding:10px; \">کیف، چمدان</td>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">وَلَد</td><td style=\"padding:10px; \">پسر، فرزند</td>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">دَخَلَ</td><td style=\"padding:10px; \">داخل شد</td>\n    </tr>\n    <tr>\n        <td style=\"padding:10px; color:#fde68a; font-size:1.2rem; font-family:'Traditional Arabic', serif;\">هَلْ؟</td><td style=\"padding:10px; \">آیا؟</td>\n        <td style=\"padding:10px;\"></td><td style=\"padding:10px;\"></td>\n    </tr>\n</tbody></table>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">متن درس (الحوار)</h3>\n<div style=\"direction:rtl; font-family:'Traditional Arabic', serif; font-size:1.3rem; color:#fde68a; line-height:2.5; text-align:right; padding:15px; background:rgba(0,0,0,0.2); border-radius:10px;\">\n    دَخَلَ مُعَلِّمُ اللُّغَةِ الْعَرَبِیَّةِ فِی الصَّفِّ مُبْتَسِماً.<br>\n    الْمُعَلِّمُ: السَّلامُ عَلَیْکُمْ.<br>\n    التَّلامیذُ: وَ عَلَیْکُمُ السَّلامُ یا أُستاذُ.<br>\n    الْمُعَلِّمُ: أَنا مُعَلِّمُ اللُّغَةِ الْعَرَبِیَّةِ. اِسْمی مُحَمَّدٌ إِسْلامی.<br>\n    التَّلامیذُ: أَهْلاً بِکُمْ یا أُستاذُ.\n</div>\n\n<div style=\"background:rgba(251,191,36,0.15); border-right:4px solid #fbbf24; padding:15px; border-radius:10px; margin:15px 0; color:#fde68a; line-height:1.8;\">\n    💡 <strong>نکته:</strong> برای پرسیدن نام کسی می‌گوییم: <span style=\"font-size:1.2rem; font-family:'Traditional Arabic', serif;\">ما اِسْمُکَ؟</span> (نام تو چیست؟ - برای مذکر) و <span style=\"font-size:1.2rem; font-family:'Traditional Arabic', serif;\">ما اِسْمُکِ؟</span> (برای مؤنث).\n</div>\n<!-- TAB: نمودار درختی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🌳 نمودار درختی فی الصف</h2>\n<div class=\"xmind-container\">\n    <div class=\"xmind-root\">فی الصف</div>\n    <div class=\"xmind-branches\">\n        <div class=\"xmind-branch\">\n            <div class=\"xmind-node\"><strong>واژگان کلاس</strong>صف، طالب، استاذ</div>\n        </div>\n        <div class=\"xmind-branch\">\n            <div class=\"xmind-node\"><strong>احوال‌پرسی</strong>السلام علیکم</div>\n        </div>\n        <div class=\"xmind-branch\">\n            <div class=\"xmind-node\"><strong>پرسش از نام</strong>ما اسمک؟</div>\n        </div>\n        <div class=\"xmind-branch\">\n            <div class=\"xmind-node\"><strong>معرفی خود</strong>اسمی محمد</div>\n        </div>\n        <div class=\"xmind-branch\">\n            <div class=\"xmind-node\"><strong>خوش‌آمدگویی</strong>أهلاً بکم</div>\n        </div>\n    </div>\n</div>\n<!-- TAB: نکات امتحانی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">📝 نکات امتحانی درس دوم</h2>\n<p style=\"color:#cbd5e1; margin-bottom:15px;\">مهم‌ترین نکاتی که برای موفقیت در امتحان این درس باید به آن‌ها توجه کنید:</p>\n\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۱: سلام و پاسخ</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">«السَّلامُ عَلَیْکُمْ» یعنی سلام بر شما. پاسخ آن «وَ عَلَیْکُمُ السَّلامُ» است.</p>\n</div>\n\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۲: پرسش از نام</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">«ما اِسْمُکَ؟» برای پسر و «ما اِسْمُکِ؟» برای دختر به معنی «نام تو چیست؟» است.</p>\n</div>\n\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۳: أهلاً بکم</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">«أَهْلاً بِکُمْ» به معنی «خوش آمدید» است.</p>\n</div>\n\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۴: واژگان</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">به تفاوت «طالب» (پسر) و «طالبة» (دختر) دقت کنید.</p>\n</div>\n<!-- TAB: آزمون -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🧪 آزمون درس دوم</h2>\n<p style=\"color:#cbd5e1; margin-bottom:20px;\">به سوالات زیر پاسخ دهید:</p>\n\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۱. ترجمه «ما اِسْمُکَ؟» چیست؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">\n        <strong>الف) نام تو چیست؟ (برای پسر)</strong> &nbsp;&nbsp; ب) نام تو چیست؟ (برای دختر) &nbsp;&nbsp; ج) او کیست؟ &nbsp;&nbsp; د) این چیست؟\n    </div>\n</div>\n\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۲. پاسخ «السَّلامُ عَلَیْکُمْ» کدام است؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">\n        الف) أهلاً بکم &nbsp;&nbsp; <strong>ب) وَ عَلَیْکُمُ السَّلامُ</strong> &nbsp;&nbsp; ج) صباح الخیر &nbsp;&nbsp; د) مع السلامة\n    </div>\n</div>\n\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۳. «طالِبَة» به چه معناست؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">\n        الف) دانش‌آموز پسر &nbsp;&nbsp; ب) معلم &nbsp;&nbsp; <strong>ج) دانش‌آموز دختر</strong> &nbsp;&nbsp; د) پزشک\n    </div>\n</div>\n\n<div style=\"background:rgba(251,191,36,0.15); border-right:4px solid #fbbf24; padding:15px; border-radius:10px; color:#fde68a;\">\n    💡 <strong>پاسخ‌نامه:</strong> ۱ (الف)، ۲ (ب)، ۳ (ج)\n</div>\n<!-- TAB: گام به گام -->\n<h2 style=\" margin-bottom:15px;\">✍️ گام به گام درس دوم</h2>\n<p style=\" line-height:1.9;\">ترجمه و پاسخ تمرین‌های درس فی الصف.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">ترجمه متن درس</h3>\n<div style=\"direction:rtl; font-family:'Traditional Arabic', serif; font-size:1.2rem; color:#fde68a; line-height:2.2; text-align:right; padding:15px; background:rgba(0,0,0,0.2); border-radius:10px;\">\n    معلم زبان عربی خندان وارد کلاس شد.<br>\n    معلم: سلام بر شما.<br>\n    دانش‌آموزان: و بر شما سلام ای استاد.<br>\n    معلم: من معلم زبان عربی هستم. نام من محمد اسلامی است.<br>\n    دانش‌آموزان: خوش آمدید ای استاد.\n</div>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">پاسخ تمرین‌ها</h3>\n<ul style=\" line-height:2; padding-right:20px;\">\n    <li><strong>پرسش:</strong> <span style=\"color:#fde68a; font-family:'Traditional Arabic', serif; font-size:1.2rem;\">مَا اسْمُکَ؟</span> (نام تو چیست؟) <br> <strong>پاسخ:</strong> <span style=\"color:#fde68a; font-family:'Traditional Arabic', serif; font-size:1.2rem;\">اِسْمِي...</span> (نام من ... است)</li>\n    <li><strong>پرسش:</strong> <span style=\"color:#fde68a; font-family:'Traditional Arabic', serif; font-size:1.2rem;\">مَا اسْمُ الْمُعَلِّمِ؟</span> (نام معلم چیست؟) <br> <strong>پاسخ:</strong> <span style=\"color:#fde68a; font-family:'Traditional Arabic', serif; font-size:1.2rem;\">اِسْمُهُ مُحَمَّدٌ إِسْلامِي.</span> (نام او محمد اسلامی است.)</li>\n    <li><strong>پرسش:</strong> <span style=\"color:#fde68a; font-family:'Traditional Arabic', serif; font-size:1.2rem;\">مَنْ دَخَلَ فِي الصَّفِّ؟</span> (چه کسی وارد کلاس شد؟) <br> <strong>پاسخ:</strong> <span style=\"color:#fde68a; font-family:'Traditional Arabic', serif; font-size:1.2rem;\">مُعَلِّمُ اللُّغَةِ الْعَرَبِيَّةِ.</span> (معلم زبان عربی.)</li>\n</ul>\n<!-- TAB: سایر -->\n<h2 style=\" margin-bottom:15px;\">🌟 سایر (بخش ویژه)</h2>\n<div style=\"background:rgba(59,130,246,0.1); border:1px dashed #3b82f6; border-radius:12px; padding:20px; text-align:center;\">\n    <p style=\"color:#93c5fd; margin-bottom:15px;\">این بخش برای محتوای اضافی مانند ویدیو، فایل صوتی یا تمرین‌های تکمیلی در نظر گرفته شده است.</p>\n    <p style=\" font-size:0.9rem;\">(شما می‌توانید با کلیک روی دکمه ویرایش، کد ویدیو آپارات یا هر محتوای دیگری را در این بخش قرار دهید).</p>\n    <div style=\"margin-top:20px;\">\n        <a href=\"#\" style=\"display:inline-block; background:#3b82f6; color:#fff; padding:10px 20px; border-radius:8px; text-decoration:none; font-weight:bold;\">🎬 مشاهده ویدیو آموزشی درس (به زودی)</a>\n    </div>\n</div>\n<!-- TAB: pdf -->\n<div class=\"block\" data-pdf=\"data:application/pdf;base64,\" data-name=\"سوغاتیاب-سند-ارائه-راهبردی-10-17-2026_02_47_PM.pdf\"></div><div class=\"block\" data-pdf=\"data:application/pdf;base64,\" data-name=\"سوشاپ.pdf\"></div><p><img src=\"data:image/jpeg;base64,\" alt=\"\"></p><table><tbody><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr></tbody></table><p><br></p>\n<!-- TAB: تصاویر مرتبط -->\n<p><img src=\"data:image/jpeg;base64,\" alt=\"\"></p><p><br></p>","r":"1uzz7jj"}]};